# -*- coding: utf-8 -*-
"""Генерация ВКР (введение, гл.1, гл.2, заключение) с оформлением по ГОСТ."""

from docx import Document
from docx.shared import Pt, Mm, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH, WD_LINE_SPACING
from docx.enum.section import WD_SECTION
from docx.enum.table import WD_TABLE_ALIGNMENT
from docx.oxml.ns import qn
from docx.oxml import OxmlElement

doc = Document()

# ---------- базовые стили ----------
normal = doc.styles['Normal']
normal.font.name = 'Times New Roman'
normal.font.size = Pt(14)
rpr = normal.element.get_or_add_rPr()
rfonts = rpr.get_or_add_rFonts()
rfonts.set(qn('w:ascii'), 'Times New Roman')
rfonts.set(qn('w:hAnsi'), 'Times New Roman')
rfonts.set(qn('w:cs'), 'Times New Roman')
pf = normal.paragraph_format
pf.line_spacing_rule = WD_LINE_SPACING.ONE_POINT_FIVE
pf.space_after = Pt(0)
pf.space_before = Pt(0)

# ---------- поля страницы ----------
sec = doc.sections[0]
sec.top_margin = Mm(20)
sec.bottom_margin = Mm(20)
sec.left_margin = Mm(30)
sec.right_margin = Mm(15)

# ---------- нумерация страниц (внизу по центру) ----------
def add_page_numbers(section):
    footer = section.footer
    footer.is_linked_to_previous = False
    p = footer.paragraphs[0]
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    run = p.add_run()
    fld1 = OxmlElement('w:fldChar'); fld1.set(qn('w:fldCharType'), 'begin')
    instr = OxmlElement('w:instrText'); instr.set(qn('xml:space'), 'preserve'); instr.text = 'PAGE'
    fld2 = OxmlElement('w:fldChar'); fld2.set(qn('w:fldCharType'), 'end')
    run._r.append(fld1); run._r.append(instr); run._r.append(fld2)
    run.font.name = 'Times New Roman'; run.font.size = Pt(14)

add_page_numbers(sec)

INDENT = Mm(12.5)  # 1.25 cm

def body(text):
    p = doc.add_paragraph()
    p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    p.paragraph_format.first_line_indent = INDENT
    p.paragraph_format.line_spacing_rule = WD_LINE_SPACING.ONE_POINT_FIVE
    # поддержка **жирного** лид-ина
    if text.startswith('**'):
        end = text.index('**', 2)
        bold_part = text[2:end]
        rest = text[end+2:]
        r = p.add_run(bold_part); r.bold = True
        p.add_run(rest)
    else:
        p.add_run(text)
    return p

def h_struct(text):
    """Заголовок структурного элемента / главы: прописными, по центру, жирный."""
    p = doc.add_paragraph()
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.space_before = Pt(6)
    p.paragraph_format.space_after = Pt(12)
    p.paragraph_format.line_spacing_rule = WD_LINE_SPACING.ONE_POINT_FIVE
    r = p.add_run(text.upper()); r.bold = True
    return p

def h_sub(text):
    """Подраздел 1.1 — слева, с отступом, жирный."""
    p = doc.add_paragraph()
    p.alignment = WD_ALIGN_PARAGRAPH.LEFT
    p.paragraph_format.first_line_indent = INDENT
    p.paragraph_format.space_before = Pt(12)
    p.paragraph_format.space_after = Pt(6)
    p.paragraph_format.line_spacing_rule = WD_LINE_SPACING.ONE_POINT_FIVE
    r = p.add_run(text); r.bold = True
    return p

def bullets(items):
    for it in items:
        p = doc.add_paragraph(style='List Bullet')
        p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
        p.paragraph_format.line_spacing_rule = WD_LINE_SPACING.ONE_POINT_FIVE
        p.paragraph_format.left_indent = INDENT
        p.add_run(it)

def numbered(items):
    for it in items:
        p = doc.add_paragraph(style='List Number')
        p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
        p.paragraph_format.line_spacing_rule = WD_LINE_SPACING.ONE_POINT_FIVE
        p.paragraph_format.left_indent = INDENT
        p.add_run(it)

def table_caption(text):
    p = doc.add_paragraph()
    p.alignment = WD_ALIGN_PARAGRAPH.LEFT
    p.paragraph_format.space_before = Pt(6)
    p.paragraph_format.line_spacing_rule = WD_LINE_SPACING.ONE_POINT_FIVE
    p.add_run(text)

def make_table(headers, rows):
    t = doc.add_table(rows=1, cols=len(headers))
    t.style = 'Table Grid'
    t.alignment = WD_TABLE_ALIGNMENT.CENTER
    hdr = t.rows[0].cells
    for i, h in enumerate(headers):
        hdr[i].text = ''
        rp = hdr[i].paragraphs[0]
        rp.alignment = WD_ALIGN_PARAGRAPH.CENTER
        run = rp.add_run(h); run.bold = True; run.font.size = Pt(12)
        run.font.name = 'Times New Roman'
    for row in rows:
        cells = t.add_row().cells
        for i, val in enumerate(row):
            cells[i].text = ''
            rp = cells[i].paragraphs[0]
            rp.alignment = WD_ALIGN_PARAGRAPH.LEFT
            run = rp.add_run(val); run.font.size = Pt(12)
            run.font.name = 'Times New Roman'
    doc.add_paragraph()

def figure(caption, placeholder=True):
    if placeholder:
        ph = doc.add_paragraph()
        ph.alignment = WD_ALIGN_PARAGRAPH.CENTER
        ph.paragraph_format.space_before = Pt(6)
        r = ph.add_run('[ место для рисунка — вставьте изображение ]')
        r.italic = True; r.font.color.rgb = RGBColor(0x80, 0x80, 0x80)
    cap = doc.add_paragraph()
    cap.alignment = WD_ALIGN_PARAGRAPH.CENTER
    cap.paragraph_format.space_after = Pt(6)
    cap.paragraph_format.line_spacing_rule = WD_LINE_SPACING.ONE_POINT_FIVE
    cap.add_run(caption)

def code(lines, caption):
    for ln in lines:
        p = doc.add_paragraph()
        p.alignment = WD_ALIGN_PARAGRAPH.LEFT
        p.paragraph_format.line_spacing_rule = WD_LINE_SPACING.SINGLE
        r = p.add_run(ln if ln else ' ')
        r.font.name = 'Courier New'; r.font.size = Pt(11)
        rpr2 = r._element.get_or_add_rPr(); rf = rpr2.get_or_add_rFonts()
        rf.set(qn('w:ascii'), 'Courier New'); rf.set(qn('w:hAnsi'), 'Courier New')
    cap = doc.add_paragraph()
    cap.alignment = WD_ALIGN_PARAGRAPH.CENTER
    cap.paragraph_format.space_after = Pt(6)
    cap.add_run(caption)

def app_sub(text):
    """Заголовок приложения: по центру, жирный."""
    p = doc.add_paragraph()
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.space_before = Pt(12)
    p.paragraph_format.space_after = Pt(6)
    p.paragraph_format.line_spacing_rule = WD_LINE_SPACING.ONE_POINT_FIVE
    r = p.add_run(text); r.bold = True
    return p

def code_plain(lines):
    for ln in lines:
        p = doc.add_paragraph()
        p.alignment = WD_ALIGN_PARAGRAPH.LEFT
        p.paragraph_format.line_spacing_rule = WD_LINE_SPACING.SINGLE
        r = p.add_run(ln if ln else ' ')
        r.font.name = 'Courier New'; r.font.size = Pt(10)
        rpr2 = r._element.get_or_add_rPr(); rf = rpr2.get_or_add_rFonts()
        rf.set(qn('w:ascii'), 'Courier New'); rf.set(qn('w:hAnsi'), 'Courier New')

def page_break():
    doc.add_page_break()

# ===================================================================
#                           ВВЕДЕНИЕ
# ===================================================================
h_struct('Введение')

body('**Актуальность.** На современном этапе развития информационных технологий наблюдается их активное внедрение в гуманитарные сферы, включая культуру и этнографическое образование. Веб-приложения становятся действенным инструментом сохранения и популяризации нематериального культурного наследия, позволяя пользователю ознакомиться с уникальными традициями коренных народов независимо от его географического положения и временных ограничений. Традиционная культура и обрядовый цикл северных народов Республики Саха (Якутия) представляют собой самобытный комплекс духовных и социальных практик, отражающих своеобразие региона. Вместе с тем суровые климатические условия, удалённость мест компактного проживания малочисленных народов и процессы глобализации затрудняют доступ к этим знаниям для широкой аудитории и ведут к риску утраты аутентичных традиций. Создание интерактивного календаря позволяет преодолеть существующие барьеры, обеспечивая доступность культурных ценностей региона для жителей республики, исследователей, студентов и туристов в едином цифровом пространстве. Таким образом, выбранная тема не только актуальна, но и обладает значительным потенциалом для развития культурного и образовательного пространства, а также для создания инновационных средств сохранения наследия народов Севера.')
body('**Объект исследования** — процесс разработки веб-приложения как средства сохранения и популяризации нематериального культурного наследия.')
body('**Предмет исследования** — интерактивный календарь традиционных праздников и обрядов северных народов Якутии, его технологические и архитектурные аспекты.')
body('**Цель** выпускной квалификационной работы — проектирование и программная реализация веб-приложения «Интерактивный календарь традиционных праздников и обрядов северных народов Республики Саха (Якутия)» для систематизации и популяризации культурного наследия региона.')
body('Для достижения поставленной цели необходимо решить следующие задачи:')
numbered([
 'определить ключевые праздники и обрядовые циклы коренных народов Севера для представления в системе;',
 'изучить современные подходы к разработке календарных веб-интерфейсов и способы цифрового сохранения этнокультурного наследия;',
 'проанализировать и обосновать выбор технологического стека — архитектуры, фреймворков и системы управления контентом и данными;',
 'спроектировать архитектуру приложения и структуру хранения контента, разработать пользовательский интерфейс с учётом специфики материала;',
 'реализовать функционал интерактивного календаря и механизм пополнения базы сообществом с последующей модерацией, провести тестирование и публикацию приложения.',
])
body('**Методы исследования:** обзор научной литературы и электронных ресурсов по тематике веб-разработки и сохранения этнокультурного наследия; системный анализ существующих календарных приложений; сравнительный анализ инструментов и библиотек для разработки клиентской и серверной частей; практическое моделирование и итеративная программная реализация.')
body('**Практическая значимость** исследования заключается в создании готового программного продукта — интерактивного календаря, который может быть непосредственно использован в образовательной, культурно-просветительской и туристической сферах деятельности Республики Саха (Якутия). Приложение развёрнуто на сервере вуза средствами контейнеризации, что обеспечивает его доступность и воспроизводимость.')
body('**Краткое содержание глав.** В первой главе рассмотрены современные подходы к созданию веб-приложений, проведён анализ популярных календарных и справочных ресурсов, а также оценены потребности пользователей и сформулированы требования к разрабатываемой системе. Во второй главе описан процесс проектирования и технической реализации приложения: обоснование технологического стека, организация хранения контента в системе управления данными, разработка пользовательского интерфейса, а также тестирование и публикация продукта. В заключении приведены основные выводы по проделанному исследованию и намечены направления дальнейшего развития.')
body('**Структура выпускной квалификационной работы:** работа состоит из введения, двух глав, заключения, списка литературы и приложений.')

page_break()

