body('**Хранение и преобразование изображений.** Все медиафайлы хранятся во встроенном хранилище Directus directus_files (см. рисунок 24). Доступ к файлу осуществляется по адресу /assets/<UUID>, причём поддерживаются преобразования «на лету» — в проекте миниатюры запрашиваются уменьшенными и сжатыми (width=400, quality=80). Поскольку идентификаторы изображений встречаются в нескольких форматах, на клиенте реализована универсальная функция разбора (см. рисунок 25), а адрес файла строится с учётом преобразований (см. рисунок 26).')
figure('Рисунок 24 — Встроенное файловое хранилище Directus (directus_files)')
code([
 'function parseImages(raw) {',
 '  if (!raw) return [];',
 '  if (Array.isArray(raw))',
 '    return raw.map(i => (typeof i === "string" ? i : i?.id)).filter(Boolean);',
 '  if (typeof raw === "string") {',
 '    const t = raw.trim();',
 '    if (UUID_RE.test(t)) return [t];',
 '    try { const p = JSON.parse(t); if (Array.isArray(p)) return p; } catch {}',
 '  }',
 '  if (raw?.id) return [raw.id];',
 '  return [];',
 '}',
], 'Рисунок 25 — Универсальный разбор поля с изображениями (parseImages)')
code([
 'export function getEventFileUrl(fileId, transforms = {}) {',
 '  const base = import.meta.env.VITE_DIRECTUS_URL;',
 '  const params = new URLSearchParams();',
 "  if (transforms.width)   params.set('width',   transforms.width);",
 "  if (transforms.quality) params.set('quality', transforms.quality);",
 '  const qs = params.toString();',
 "  return `${base}/assets/${fileId}${qs ? '?' + qs : ''}`;",
 '}',
], 'Рисунок 26 — Построение адреса файла с преобразованиями width/quality (getEventFileUrl)')
body('**Двухуровневая организация контента.** Содержательно праздники формируются из двух источников: верифицированного ядра (коллекция holidays) и одобренных пользовательских предложений (записи propsals с approved = true). Обе выборки приводятся к единому виду и объединяются функцией mergeHolidaysAndProposals (см. рисунок 27), после чего одобренное предложение становится полноценным элементом каталога и календаря. Обращения к коллекциям идут через Express-шлюз, который проставляет заголовки кэширования (Cache-Control 300 с для каталога и 60 с для мероприятий). Перечень конечных точек доступа к данным приведён в таблице 8.')
code([
 'export function mergeHolidaysAndProposals(holidays = [], proposals = []) {',
 '  return [',
 '    ...holidays,',
 '    ...proposals.map(p => ({',
 '      id: `proposal-${p.id}`,',
 '      title: p.title, people: p.people,',
 '      description: p.description,',
 '      date: p.date || p.holiday_date || "",',
 '      images: resolveImages(p), isProposal: true,',
 '    })),',
 '  ];',
 '}',
], 'Рисунок 27 — Объединение каталога и одобренных предложений (mergeHolidaysAndProposals)')
table_caption('Таблица 8 — Конечные точки доступа к данным и их параметры')
